import{_ as i,o as a,c as t,a5 as r}from"./chunks/framework.CsGesDJn.js";const f=JSON.parse('{"title":"Unified AI Credit (DA-974)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/credit-unification/spec.md","filePath":"feature/credit-unification/spec.md"}'),n={name:"feature/credit-unification/spec.md"};function s(o,e,d,c,l,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="unified-ai-credit-da-974" tabindex="-1">Unified AI Credit (DA-974) <a class="header-anchor" href="#unified-ai-credit-da-974" aria-label="Permalink to &quot;Unified AI Credit (DA-974)&quot;">​</a></h1><h2 id="objective-and-confirmed-business-rules" tabindex="-1">Objective and confirmed business rules <a class="header-anchor" href="#objective-and-confirmed-business-rules" aria-label="Permalink to &quot;Objective and confirmed business rules&quot;">​</a></h2><p>Use DA-974 accounting for every new billable AI request. Preserve Caption context, prompts, response fields, choice/history and Video content behavior. Admin configures fixed per-operation prices; token/GPU/Vast billing and Payment/Subscription provisioning are out of scope.</p><ul><li>Caption generate/refine/adapt all use CAPTION_VARIANTS; one successful request costs one frozen price, regardless of returned captions/platforms.</li><li>Agency funds are shared. Owner has no personal ceiling; Manager/Creator inherit configured ceilings (system fallback 10). Client cannot generate. Plan funds are used first.</li><li>Reserve before dispatch, settle once on usable success, release on definite failure. Unknown/timeout stays held, without automatic redispatch/refund.</li><li>Technical retries use the same Idempotency-Key and request identity; different actions/payloads conflict. Missing/disabled prices block before dispatch; never invent prices.</li><li>Preserve legacy tables/history without importing seeded usage or balances. Legacy Video jobs retain their original refund mechanism only; new jobs never charge the old ledger.</li></ul><h2 id="api-and-acceptance-criteria" tabindex="-1">API and acceptance criteria <a class="header-anchor" href="#api-and-acceptance-criteria" aria-label="Permalink to &quot;API and acceptance criteria&quot;">​</a></h2><p>Workspace Caption/Video POST routes require Idempotency-Key. Existing URLs/request bodies/response field names remain; credit amounts support bigint instead of int. New Video responses distinguish held credit from settled credit additively. Retries reuse persisted output and history IDs, including when server-generated context changes. No arbitrary upstream path is accepted from clients.</p><p>Workspace credits and Dashboard use DA-974. Dashboard retains deprecated calendar-month fields with calendar-month semantics, adds explicit subscription-period usage/bounds and an unavailable state. No fallback to legacy/fabricated zero when credit setup/schema is missing. Existing free styles/status/history/choice/trend-fit stay free.</p><h2 id="ui-states" tabindex="-1">UI states <a class="header-anchor" href="#ui-states" aria-label="Permalink to &quot;UI states&quot;">​</a></h2><p>Reuse existing theme/components; no page redesign or mock Studio integration. Dashboard labels use parallel vi/en keys for subscription period and unavailable credit. Existing light/dark tokens, keyboard access and mobile layout remain. Credit caches are user scoped; workspace AI mutations invalidate the relevant reports.</p><h2 id="definition-of-done" tabindex="-1">Definition of done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of done&quot;">​</a></h2><p>Compile/typecheck and isolated database/provider-fixture checks pass; delta/init parity and repeat application verified; no shared DB or real paid provider writes. Document remaining live deployment and Admin price prerequisites. No executable test artifacts committed.</p>',11)])])}const h=i(n,[["render",s]]);export{f as __pageData,h as default};
